const ico=(k,sz)=>`<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"${sz?` width="${sz}" height="${sz}"`:''}>${ICO[k]||ICO.spark}</svg>`;
function photoErr(img){const l=(img.dataset.try||'jpeg,png,webp,svg').split(',');const n=l.shift();img.dataset.try=l.join(',');if(n){img.src=img.dataset.base+'.'+n}else{img.onerror=null}}
const photo=(k,alt,cls='')=>`<img class="${cls}" src="${PHOTO[k]}.jpg" alt="${esc(alt)}" decoding="async">`;
const wordsAtLevel=id=>W.filter(w=>Number(w.difficulty)===Number(id));
const levelTag=w=>DIFFICULTIES.find(x=>x.id===Number(w.difficulty))?.name||'Unclassified';
function setGameLevel(mode,val){D.gameLevels[mode]=Number(val);save()}
/* Word progress: a word counts as "learned" once it has been answered correctly at least once. */
function wordProgress(f){const ws=f?W.filter(f):W;let m=0,fa=0,ln=0;ws.forEach(w=>{const p=D.p[w.id];if(!p||!(p.c>0))return;const k=sOf(p);if(k=='mastered')m++;else if(k=='familiar')fa++;else ln++});const learned=m+fa+ln,t=ws.length;return{t,learned,m,fa,ln,left:t-learned,pct:t?Math.round(learned/t*100):0}}
function progressCard(){const p=wordProgress(),seg=n=>p.t?(n/p.t*100).toFixed(2):0;
 return`<section class="card progress-card"><div class="progress-head"><div><span class="eyebrow">YOUR WORD PROGRESS</span><h2>${p.learned} <small>/ ${p.t} words learned</small></h2></div><span class="progress-pct">${p.pct}%</span></div>
 <div class="stack-bar" role="img" aria-label="${p.pct}% of words learned"><i class="seg-m" style="width:${seg(p.m)}%"></i><i class="seg-f" style="width:${seg(p.fa)}%"></i><i class="seg-l" style="width:${seg(p.ln)}%"></i></div>
 <div class="legend"><span><i class="dot seg-m"></i>Mastered <b>${p.m}</b></span><span><i class="dot seg-f"></i>Familiar <b>${p.fa}</b></span><span><i class="dot seg-l"></i>Learning <b>${p.ln}</b></span><span><i class="dot seg-n"></i>Not started <b>${p.left}</b></span></div>
 <div class="level-progress">${DIFFICULTIES.map(l=>{const q=wordProgress(w=>Number(w.difficulty)===l.id);return`<div class="lp-row"><span>${l.name}</span><div class="bar"><i style="width:${q.pct}%"></i></div><b>${q.learned}/${q.t}</b><small>${q.pct}%</small></div>`}).join('')}</div>
 <p class="micro">একটি শব্দ কমপক্ষে একবার সঠিক উত্তর দিলে "learned" ধরা হয়। Mastered হতে আলাদা আলাদা দিনে বারবার সঠিক উত্তর লাগে।</p></section>`}
function progressMini(){const p=wordProgress();return`<div class="card progress-mini"><div class="progress-head"><b>Word progress</b><span class="progress-pct sm">${p.pct}%</span></div><div class="bar"><i style="width:${p.pct}%"></i></div><p class="micro">${p.learned} of ${p.t} words learned · ${p.left} still to go</p></div>`}

function theme(){document.documentElement.dataset.t=activeTheme()}
function cycleTheme(){const a=['midnight','paper'],i=a.indexOf(activeTheme());D.theme=a[(i+1)%a.length];save();theme();render()}
