let MT='active';
const mistWords=f=>W.filter(w=>D.mist[w.id]&&f(D.mist[w.id]));
V.mistakes=()=>{const act=mistWords(m=>!m.fixed),fx=mistWords(m=>m.fixed),tot=Object.values(D.mist).reduce((a,m)=>a+m.w,0),ex=D.ses.filter(x=>x.mode=='mistakes').length,cnt=[{v:5,t:'5 questions'},{v:10,t:'10 questions'},{v:20,t:'20 questions'},{v:999,t:'All weak words'}];
 return`<div class="page-heading"><div><span class="eyebrow">LEARN FROM YOUR MISTAKES</span><h1>Mistakes</h1><p class="sub">যেসব শব্দে ভুল হয়েছে সেগুলো এখানে জমা হয়। একটি শব্দ পরপর ৩ বার সঠিক হলে "Recovered" হয়ে যায়।</p></div><span class="count-tile"><b>${act.length}</b><small>TO FIX</small></span></div>
 <section class="profile-progress-section"><div class="section-head"><div><span class="eyebrow">YOUR ACHIEVEMENTS</span><h2>Learning snapshot</h2></div><a class="text-link" href="#analytics">Full analytics ↗</a></div><div class="grid profile-stats">${stat(act.length,'Words to fix')}${stat(fx.length,'Recovered')}${stat(tot,'Wrong answers')}${stat(ex,'Mistake exams')}</div>
 <section class="card exam-card"><div class="exam-copy"><span class="eyebrow">MISTAKES EXAM</span><h2>Test yourself on weak words</h2><p class="sub">শুধু ভুল করা শব্দ থেকে মিক্সড প্রশ্ন — MCQ, শব্দ সাজানো, বাক্য সাজানো, Odd one out ইত্যাদি।</p></div><div class="exam-actions">${ddHTML('mx-count',cnt,10)}<button class="btn pri" onclick="startMistakeExam()" ${act.length?'':'disabled'}>Start exam →</button><button class="btn" onclick="start('boss')">Boss battle</button></div></section>
 <div id="mist-body"></div>`};
const setMT=k=>{MT=k;drawMist()};
function drawMist(){const el=$('#mist-body');if(!el)return;const act=mistWords(m=>!m.fixed).sort((a,b)=>D.mist[b.id].w-D.mist[a.id].w||D.mist[b.id].t-D.mist[a.id].t),fx=mistWords(m=>m.fixed).sort((a,b)=>D.mist[b.id].fixed-D.mist[a.id].fixed),ex=D.ses.filter(x=>x.mode=='mistakes'||x.mode=='boss').sort((a,b)=>b.t-a.t);
 const dt=t=>new Date(t).toLocaleDateString('en',{day:'numeric',month:'short'});
 const row=(w,m,fixed)=>`<article class="mist-row"><button class="mist-word" onclick="openWord('${w.id}')"><b>${esc(w.en)}</b><small class="bn">${esc(short(w.bn))}</small></button><div class="mist-meta"><span class="chip">${m.w} wrong</span><span class="chip">${fixed?'Recovered '+dt(m.fixed):'Last '+dt(m.t)}</span>${fixed?'':`<span class="mist-dots" title="${m.ok}/3 correct in a row">${[0,1,2].map(i=>`<i class="${i<m.ok?'on':''}"></i>`).join('')}</span>`}</div></article>`;
 const tabs=[['active','Needs practice',act.length],['fixed','Recovered',fx.length],['exams','Exam results',ex.length]];
 let body;
 if(MT=='active')body=act.length?act.map(w=>row(w,D.mist[w.id],0)).join(''):`<div class="card empty"><h2>Nothing to fix</h2><p>Wrong answers from practice and games will appear here.</p></div>`;
 else if(MT=='fixed')body=fx.length?fx.map(w=>row(w,D.mist[w.id],1)).join(''):`<div class="card empty"><h2>No recovered words yet</h2><p>Answer a weak word correctly 3 times in a row and it moves here.</p></div>`;
 else body=ex.length?ex.map(histRow).join(''):`<div class="card empty"><h2>No mistake exams yet</h2><p>Start a Mistakes exam or Boss battle above.</p></div>`;
 el.innerHTML=`<div class="tabs" role="tablist">${tabs.map(([k,n,c])=>`<button class="tab ${MT==k?'on':''}" role="tab" onclick="setMT('${k}')">${n}<span>${c}</span></button>`).join('')}</div><div class="hist-list">${body}</div>`}
