/* Local-first startup: render saved/bundled data immediately (including file://),
   then refresh the primary vocabulary from the project-root vocabulary.json file. Learning
   progress lives in D.p / sessions / achievements and is never reset here. */
W=Array.isArray(D.words)?D.words:[];
// Refresh canonical fields for the bundled collection, preserving learner-added
// words and optional metadata while updating old saved entries to the reviewed data.
const existingWords=new Map(W.map(w=>[w.id||nid(w.en||''),w]));
BUNDLED_WORDS.forEach(w=>{
 const existing=existingWords.get(w.id);
 if(existing)Object.assign(existing,w);
 else{const copy={...w};W.push(copy);existingWords.set(w.id,copy)}
});
W.forEach(w=>{if(w.difficulty==null||isNaN(Number(w.difficulty))){w.difficulty=3;w.level='Intermediate';w.classificationStatus=w.classificationStatus||'auto'}});
save();
render();
// Hosted deployments can fetch the project-root vocabulary.json; offline and file:// use the embedded fallback.
syncRemoteVocabulary({silent:true});
